		function buatInputKoordinat(idInput, x, y, lebar, tinggi, placeholderText) {
		    // Hapus elemen jika sudah ada sebelumnya
		    var elLama = document.getElementById(idInput);
		    if (elLama) elLama.remove();
		
		    var canvas = document.getElementById("canvas");
		    if (!canvas) return null;
		
		    var input = document.createElement("input");
		    input.id = idInput;
		    input.type = "text";
		    input.placeholder = placeholderText;
		
		    // Styling transparan agar menyatu dengan desain kotak
		    input.style.position = "absolute";
		    input.style.textAlign = "center";
		    input.style.fontSize = "14px";
		    input.style.fontFamily = "sans-serif";
		    input.style.background = "transparent";
		    input.style.border = "none";
		    input.style.outline = "none";
		    input.style.zIndex = "100";
		
		    // Perhitungan posisi berdasarkan skala Canvas di Browser
		    var canvasRect = canvas.getBoundingClientRect();
		    var scaleX = canvasRect.width / canvas.width;
		    var scaleY = canvasRect.height / canvas.height;
		
		    // Menentukan posisi presisi (X, Y, Lebar, Tinggi)
		    input.style.left = (canvasRect.left + window.scrollX + (x * scaleX)) + "px";
		    input.style.top = (canvasRect.top + window.scrollY + (y * scaleY)) + "px";
		    input.style.width = (lebar * scaleX) + "px";
		    input.style.height = (tinggi * scaleY) + "px";
		
		    document.body.appendChild(input);
		    return input;
		}
		
