	cjs.MovieClip.apply(this,[props]);

	// timeline functions:
	this.frame_0 = function() {
		this.stop();
		var root = this;
		
		// Set pilihan default jika belum ada
		if (!window.karakterTerpilih) {
		    window.karakterTerpilih = "cowo";
		}
		
		// Fungsi khusus memperbarui transparansi KARTU KARAKTER SAJA
		function updateTampilanKarakter() {
		    if (root.btn_cowo) {
		        root.btn_cowo.alpha = (window.karakterTerpilih === "cowo") ? 1.0 : 0.4;
		    }
		    if (root.btn_cewe) {
		        root.btn_cewe.alpha = (window.karakterTerpilih === "cewe") ? 1.0 : 0.4;
		    }
		}
		
		// Pastikan tombol PILIH selalu terang (alpha = 1)
		if (root.btn_pilih) {
		    root.btn_pilih.alpha = 1.0;
		}
		
		// Jalankan set tampilan awal
		updateTampilanKarakter();
		
		// 1. Klik Karakter Cowo
		if (root.btn_cowo) {
		    root.btn_cowo.cursor = "pointer";
		    root.btn_cowo.mouseChildren = false;
		    root.btn_cowo.removeAllEventListeners("click");
		    root.btn_cowo.on("click", function() {
		        window.karakterTerpilih = "cowo";
		        updateTampilanKarakter();
		    });
		}
		
		// 2. Klik Karakter Cewe
		if (root.btn_cewe) {
		    root.btn_cewe.cursor = "pointer";
		    root.btn_cewe.mouseChildren = false;
		    root.btn_cewe.removeAllEventListeners("click");
		    root.btn_cewe.on("click", function() {
		        window.karakterTerpilih = "cewe";
		        updateTampilanKarakter();
		    });
		}
		
		// 3. Klik Tombol PILIH
		if (root.btn_pilih) {
		    root.btn_pilih.cursor = "pointer";
		    root.btn_pilih.mouseChildren = false;
		    root.btn_pilih.removeAllEventListeners("click");
		    root.btn_pilih.on("click", function() {
		        // Bersihkan sisa elemen HTML jika ada
		        var elNama = document.getElementById("html_nama");
		        var elKelas = document.getElementById("html_kelas");
		        var elPeringatan = document.getElementById("html_peringatan");
		        if (elNama) elNama.remove();
		        if (elKelas) elKelas.remove();
		        if (elPeringatan) elPeringatan.remove();
		
		        // Pindah ke frame berikutnya
		        exportRoot.gotoAndStop(8);
		    });
		}
	}

